def flatten(nested_dict, separator="_", root_keys_to_ignore=set()):
    """
    Flatten a nested dictionary. Compatible with the flatten_json package
    used by the project's tests (flatten_json v0.1.14 behavior).
    """
    non_flat_dict = dict(nested_dict)
    flat_dict = dict()
    for key, value in non_flat_dict.items():
        if key in root_keys_to_ignore:
            flat_dict[separator + key] = value
        elif isinstance(value, (dict, list, tuple, set)):
            if isinstance(value, dict):
                sub_dict = value
            else:
                sub_dict = dict(enumerate(value))
            flat_value_dict = flatten(sub_dict, separator, root_keys_to_ignore)
            for flat_key, flat_value in flat_value_dict.items():
                flat_dict[separator + key + flat_key] = flat_value
        else:
            flat_dict[separator + key] = value
    return flat_dict

