def flatten(nested_dict, separator="_", root_keys_to_ignore=()):
    flattened_dict = {}

    def flatten_x(x, name="", root_keys_to_ignore=()):
        if type(x) is dict:
            for a in x:
                if a not in root_keys_to_ignore:
                    flatten_x(x[a], name + a + separator)
        elif type(x) is list:
            i = 0
            for a in x:
                flatten_x(a, name + str(i) + separator)
                i += 1
        else:
            flattened_dict[name[:-1]] = x

    flatten_x(nested_dict, "", root_keys_to_ignore)
    return flattened_dict

