def _construct_key(previous_key, separator, new_key):
    if previous_key:
        return f"{previous_key}{separator}{new_key}"
    return f"{new_key}"


def flatten(nested_dict, separator="_", root_keys_to_ignore=set()):
    if not isinstance(nested_dict, (dict, list)):
        raise TypeError("flatten only accepts dict and list")

    if isinstance(nested_dict, list) and len(nested_dict) == 0:
        return {}

    flattened_dict = {}

    if isinstance(nested_dict, dict):
        root_items = nested_dict.items()
    elif isinstance(nested_dict, list):
        root_items = enumerate(nested_dict)

    for key, value in root_items:
        if key in root_keys_to_ignore:
            flattened_dict[_construct_key(None, separator, key)] = value
            continue

        if isinstance(value, (dict, list)):
            sub_flattened_dict = flatten(value, separator, root_keys_to_ignore)
            for sub_key, sub_value in sub_flattened_dict.items():
                flattened_dict[_construct_key(key, separator, sub_key)] = sub_value
        else:
            flattened_dict[_construct_key(None, separator, key)] = value

    return flattened_dict

