import json, sys
sys.path.insert(0, '/testbed/scripts')
import format_json

def get_notes(x, key="note"):
    if key not in x:
        return []
    v = x[key]
    return v if isinstance(v, list) else [v]

def extract_leave_with_gmode_setup_strats(node_json):
    if "leaveWithGModeSetup" not in node_json:
        return []
    node_id = node_json["id"]
    strats = []
    for setup_json in node_json["leaveWithGModeSetup"]:
        setup_notes = get_notes(setup_json, "note")
        setup_dev_notes = get_notes(setup_json, "devNote")
        knockback = setup_json.get("knockback")
        for strat_json in setup_json["strats"]:
            strat = dict(strat_json)
            strat_name = strat.pop("name")
            notes = setup_notes + get_notes(strat, "note")
            dev_notes = setup_dev_notes + get_notes(strat, "devNote")
            strat.pop("note", None)
            strat.pop("devNote", None)
            new_strat = {
                "link": [node_id, node_id],
                "name": "G-Mode Setup - " + strat_name,
                **strat,
                "exitCondition": {
                    "leaveWithGModeSetup": {}
                }
            }
            if knockback is not None:
                new_strat["exitCondition"]["leaveWithGModeSetup"]["knockback"] = knockback
            if notes:
                new_strat["note"] = notes
            if dev_notes:
                new_strat["devNote"] = dev_notes
            strats.append(new_strat)
    del node_json["leaveWithGModeSetup"]
    return strats

def extract_gmode_immobile_strats(node_json):
    if "gModeImmobile" not in node_json:
        return []
    immobile = node_json["gModeImmobile"]
    node_id = node_json["id"]
    strat = {
        "link": [node_id, node_id],
        "name": "G-Mode Regain Mobility",
        "requires": immobile["requires"],
        "gModeRegainMobility": {},
    }
    if "note" in immobile:
        strat["note"] = immobile["note"]
    if "devNote" in immobile:
        strat["devNote"] = immobile["devNote"]
    del node_json["gModeImmobile"]
    return [strat]

def get_gmode_entrance_list(requires):
    # returns (from_nodes, entrance_condition, filtered_reqs)
    from_nodes_list = None
    entrance_condition = None
    filtered = []
    for req in requires:
        if isinstance(req, dict) and "comeInWithGMode" in req:
            ci = req["comeInWithGMode"]
            if from_nodes_list is not None:
                raise RuntimeError("Non-unique comeInWithGMode")
            from_nodes_list = ci["fromNodes"]
            entrance_condition = {
                "comeInWithGMode": {
                    "mode": ci["mode"],
                    "morphed": ci["artificialMorph"],
                }
            }
            if "mobility" in ci:
                entrance_condition["comeInWithGMode"]["mobility"] = ci["mobility"]
        else:
            filtered.append(req)
    if from_nodes_list is None:
        raise RuntimeError("No comeInWithGMode requirement at top level")
    return from_nodes_list, entrance_condition, filtered

def extract_leave_with_gmode_strats(node_json):
    if "leaveWithGMode" not in node_json:
        return []
    node_id = node_json["id"]
    strats = []
    for setup_json in node_json["leaveWithGMode"]:
        setup_notes = get_notes(setup_json, "note")
        setup_dev_notes = get_notes(setup_json, "devNote")
        morphed = setup_json["leavesWithArtificialMorph"]
        for strat_json in setup_json["strats"]:
            strat = dict(strat_json)
            strat_name = strat["name"]
            from_nodes, entrance_condition, filtered = get_gmode_entrance_list(strat["requires"])
            notes = setup_notes + get_notes(strat, "note")
            dev_notes = setup_dev_notes + get_notes(strat, "devNote")
            strat.pop("note", None)
            strat.pop("devNote", None)
            # reconstruct requires in filtered form for the copied strat
            new_requires = list(filtered)
            base = dict(strat)
            base["requires"] = new_requires
            for fn in from_nodes:
                new_strat = {
                    "link": [fn, node_id],
                    **base,
                    "entranceCondition": entrance_condition,
                    "exitCondition": {
                        "leaveWithGMode": {
                            "morphed": morphed
                        }
                    }
                }
                if notes:
                    new_strat["note"] = notes
                if dev_notes:
                    new_strat["devNote"] = dev_notes
                strats.append(new_strat)
    del node_json["leaveWithGMode"]
    return strats

def extract_come_in_with_gmode_strat(strat_json):
    # returns list of strats (possibly multiple if multi fromNodes), or None if no conversion
    requires = strat_json.get("requires", [])
    cnt = 0
    for req in requires:
        if isinstance(req, dict) and "comeInWithGMode" in req:
            cnt += 1
    if cnt == 0:
        return None
    if cnt > 1:
        print("WARN: multiple comeInWithGMode in", strat_json.get("name"))
        return None
    try:
        from_nodes, entrance_condition, filtered = get_gmode_entrance_list(requires)
    except Exception as e:
        print("WARN: skip comeInWithGMode in", strat_json.get("name"), e)
        return None
    out = []
    for fn in from_nodes:
        new_strat = {
            "link": [fn, strat_json["link"][1]],
            "name": strat_json["name"],
        }
        if strat_json.get("notable") == True:
            new_strat["notable"] = True
        new_strat["entranceCondition"] = entrance_condition
        new_strat["requires"] = filtered
        for k, v in strat_json.items():
            if k not in new_strat:
                new_strat[k] = v
        out.append(new_strat)
    return out

def create_missing_links(room_json):
    strat_link_sets = {}
    for strat in room_json["strats"]:
        fn, tn = strat["link"]
        strat_link_sets.setdefault(fn, set()).add(tn)
    link_from_map = {}
    room_link_sets = {}
    for link_from in room_json["links"]:
        link_from_map[link_from["from"]] = link_from["to"]
        room_link_sets[link_from["from"]] = {l["id"] for l in link_from["to"]}
    for fn, to_set in strat_link_sets.items():
        if fn not in room_link_sets:
            new_li = {"from": fn, "to": []}
            link_from_map[fn] = new_li["to"]
            room_link_sets[fn] = set()
            room_json["links"].append(new_li)
        for tn in to_set:
            if tn not in room_link_sets[fn]:
                link_from_map[fn].append({"id": tn})
                room_link_sets[fn].add(tn)
    room_json["links"].sort(key=lambda x: x["from"])
    for lf in room_json["links"]:
        lf["to"].sort(key=lambda x: x["id"])

def migrate_room(room_json):
    new_strats = []
    for strat_json in room_json["strats"]:
        converted = extract_come_in_with_gmode_strat(strat_json)
        if converted is not None:
            new_strats.extend(converted)
        else:
            new_strats.append(strat_json)
    for node_json in room_json["nodes"]:
        new_strats.extend(extract_leave_with_gmode_setup_strats(node_json))
        new_strats.extend(extract_leave_with_gmode_strats(node_json))
        new_strats.extend(extract_gmode_immobile_strats(node_json))
    new_strats.sort(key=lambda x: x["link"])
    room_json["strats"] = new_strats

if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('paths', nargs='+', type=str)
    args = parser.parse_args()
    for p in args.paths:
        room_json = json.load(open(p))
        migrate_room(room_json)
        create_missing_links(room_json)
        open(p, 'w').write(format_json.format(room_json, indent=2) + "\n")
        print("Processed", p)

